package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string          // PIC X(5) @0 len=5
	OrStat  string          // PIC X(1) @5 len=1
	OrQty   int64           // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderFile *os.File
var scanner *bufio.Scanner
var curRec OrderRec

func isInputDone() bool { return WsEofFlag == "Y" }

func truncHigh(v decimal.Decimal, intDigits int) decimal.Decimal {
	mod := decimal.New(1, int32(intDigits))
	abs := v.Abs()
	if abs.Cmp(mod) >= 0 {
		rem := abs.Mod(mod)
		if v.IsNegative() {
			return rem.Neg()
		}
		return rem
	}
	return v
}

func formatCount(n int64) string {
	n = n % 100
	if n < 0 {
		n += 100
	}
	return fmt.Sprintf("%02d", n)
}

func formatEdited(v decimal.Decimal, picture string) string {
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	fracDigits := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' {
			fracDigits++
		}
	}
	abs := v.Abs()
	var sFixed string
	if fracDigits > 0 {
		sFixed = abs.StringFixed(int32(fracDigits))
	} else {
		sFixed = abs.StringFixed(0)
	}
	var sInt, sFrac string
	if fracDigits > 0 {
		parts := strings.SplitN(sFixed, ".", 2)
		sInt = parts[0]
		if len(parts) > 1 {
			sFrac = parts[1]
		} else {
			sFrac = strings.Repeat("0", fracDigits)
		}
		if len(sFrac) < fracDigits {
			sFrac = sFrac + strings.Repeat("0", fracDigits-len(sFrac))
		} else if len(sFrac) > fracDigits {
			sFrac = sFrac[:fracDigits]
		}
	} else {
		if idx := strings.Index(sFixed, "."); idx >= 0 {
			sInt = sFixed[:idx]
		} else {
			sInt = sFixed
		}
		sFrac = ""
	}
	if len(sInt) > intDigits {
		sInt = sInt[len(sInt)-intDigits:]
	} else if len(sInt) < intDigits {
		sInt = strings.Repeat("0", intDigits-len(sInt)) + sInt
	}
	var intFormatted strings.Builder
	digitIdx := 0
	stillSuppress := true
	for _, ch := range intPic {
		if ch == ',' {
			if stillSuppress {
				intFormatted.WriteRune(' ')
			} else {
				intFormatted.WriteRune(',')
			}
		} else if ch == 'Z' || ch == '9' {
			dc := sInt[digitIdx]
			digitIdx++
			if ch == 'Z' && stillSuppress && dc == '0' {
				intFormatted.WriteRune(' ')
			} else {
				intFormatted.WriteRune(rune(dc))
				stillSuppress = false
			}
		} else {
			intFormatted.WriteRune(ch)
		}
	}
	if fracDigits > 0 {
		var fracFormatted strings.Builder
		fracIdx := 0
		for _, ch := range fracPic {
			if ch == '9' || ch == 'Z' {
				if fracIdx < len(sFrac) {
					fracFormatted.WriteByte(sFrac[fracIdx])
					fracIdx++
				} else {
					fracFormatted.WriteRune('0')
				}
			} else {
				fracFormatted.WriteRune(ch)
			}
		}
		return intFormatted.String() + "." + fracFormatted.String()
	}
	return intFormatted.String()
}

func parseOrderRec(line string) {
	curRec.OrId = line[0:5]
	curRec.OrStat = line[5:6]
	qtyStr := line[6:9]
	qtyTrim := strings.TrimSpace(qtyStr)
	var qty int64 = 0
	if qtyTrim != "" {
		filtered := ""
		for _, ch := range qtyTrim {
			if ch >= '0' && ch <= '9' {
				filtered += string(ch)
			}
		}
		if filtered != "" {
			if v, err := strconv.ParseInt(filtered, 10, 64); err == nil {
				qty = v
			}
		}
	}
	curRec.OrQty = qty

	priceStr := line[9:15]
	priceTrim := strings.TrimSpace(priceStr)
	var price decimal.Decimal = decimal.NewFromInt(0)
	if priceTrim != "" {
		filtered := ""
		for _, ch := range priceTrim {
			if ch >= '0' && ch <= '9' {
				filtered += string(ch)
			}
		}
		if filtered != "" {
			if v, err := strconv.ParseInt(filtered, 10, 64); err == nil {
				price = decimal.New(v, -2)
			}
		}
	}
	curRec.OrPrice = price
}

func OpenInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	orderFile = f
	scanner = bufio.NewScanner(f)
	buf := make([]byte, 4096)
	scanner.Buffer(buf, 1024*1024)
}

func CloseInput() {
	if orderFile != nil {
		orderFile.Close()
	}
}

func ReadPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		parseOrderRec(line)
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ShowPara() {
	WsQtyEd = formatEdited(decimal.NewFromInt(curRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(curRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s%s%s%s%s%s%s%s%s\n", curRec.OrId, " ", curRec.OrStat, " ", WsQtyEd, " ", WsPriceEd, " ", WsTotalEd)
}

func ProcessPara() {
	WsTotal = decimal.NewFromInt(0)
	if curRec.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Printf("%s%s\n", curRec.OrId, " BAD QTY")
	} else if curRec.OrStat == "N" {
		prod := decimal.NewFromInt(curRec.OrQty).Mul(curRec.OrPrice)
		prodTrunc := prod.Truncate(2)
		WsTotal = truncHigh(prodTrunc, 8)
		WsNewCount = (WsNewCount + 1) % 100
		ShowPara()
	} else if curRec.OrStat == "S" {
		prod := decimal.NewFromInt(curRec.OrQty).Mul(curRec.OrPrice).Mul(decimal.RequireFromString("1.05"))
		rounded := prod.Round(2)
		WsTotal = truncHigh(rounded, 8)
		WsShipCount = (WsShipCount + 1) % 100
		ShowPara()
	} else if curRec.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		ShowPara()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Printf("%s%s%s\n", curRec.OrId, " BAD STATUS ", curRec.OrStat)
	}
	sum := WsGrand.Add(WsTotal)
	WsGrand = truncHigh(sum, 10)
	ReadPara()
}

func SummaryPara() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s%s%s%s%s%s\n", "NEW: ", formatCount(WsNewCount), " SHIPPED: ", formatCount(WsShipCount), " CANCELLED: ", formatCount(WsCancelCount))
	fmt.Printf("%s%s%s%s\n", "INVALID: ", formatCount(WsInvalid), " BAD QTY: ", formatCount(WsBadQty))
	fmt.Printf("%s%s\n", "GRAND TOTAL: ", WsGrandEd)
}

func MainPara() {
	OpenInput()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	CloseInput()
	SummaryPara()
}

func main() {
	MainPara()
}
